head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > applyColumnClass]<br/>inputType='select','autoComplete' 일때 Column 의 class 속성값을 아이템 리스트에 동일하게 적용할지 설정합니다.<br/>Column 의 class 속성이 설정된 경우에 동작합니다.",
    "validation" : [
        "true 설정 시 Column 의 class 속성값을 팝업창의 아이템 리스트에 동일하게 적용합니다.",
        "true 설정 시 아이템리스트의 최상위 div 요소에 class 속성으로 적용됩니다.",
        "false(기본값) 설정 시 Column 의 class 속성값을 팝업창의 아이템 리스트에 적용하지 않습니다.",
        "미설정 시 기본값 false 로 동작합니다.",
        "Column 의 class 속성이 설정된 경우에 동작합니다.",
        "inputType 이 'select' 또는 'autoComplete' 인 경우에만 동작합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // applyColumnClass 동작 조건 라벨 생성
    $c.gcm.createLabel('label="Column0: inputType=select  + class=apc_color_blue (조건 충족)"', '', 'label1');
    $c.gcm.createLabel('label="Column1: inputType=autoComplete + class=apc_color_green (조건 충족)"', '', 'label2');
    $c.gcm.createLabel('label="Column2: inputType=select  + class 미설정 (적용할 class 자체가 없음)"', '', 'label3');
    $c.gcm.createLabel('label="Column3: inputType=text   + class=apc_color_red  (inputType 조건 불성립)"', '', 'label4');

    // dataList 직접 생성 (각 컬럼별 choices 와 매칭되는 값으로 초기화)
    let grp_comp_dl = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strDl = '';
    strDl += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDl += '<w2:columnInfo>';
    strDl += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDl += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDl += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDl += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDl += '</w2:columnInfo>';
    strDl += '<w2:data use="true">';
    strDl += '<w2:row>';
    strDl += '<col1><![CDATA[A]]></col1>';
    strDl += '<col2><![CDATA[Apple]]></col2>';
    strDl += '<col3><![CDATA[X]]></col3>';
    strDl += '<col4><![CDATA[hello]]></col4>';
    strDl += '</w2:row>';
    strDl += '</w2:data>';
    strDl += '</w2:dataList>';
    // dataList 는 dynamicCreate 미지원 → $p.data.create(strXml) 로 생성
    $p.data.create(strDl);

    // 조건 설정 - applyColumnClass
    let applyColumnClassText = con_applyColumnClass.getText();

    // target 생성 (column 별로 inputType / class 다르게 적용한 custom gridView)
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    let applyAttr = applyColumnClassText === '' ? '' : 'applyColumnClass="' + applyColumnClassText + '" ';

    // editModeEvent=onclick 으로 셀 1회 클릭만으로 편집 모드 진입 → 팝업 표시
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + applyAttr + 'editModeEvent="onclick" dataList="data:dlt_bind" checkAllType="false" id="" style="width:600px;height:200px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" inputType="text" id="column1" value="select+class"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="column2" value="autoComplete+class"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="column3" value="select(class 미설정)"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="column4" value="text+class"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // col1: inputType=select + class 설정 (적용 대상)
    strTarget += '<w2:column width="150" inputType="select" class="apc_color_blue" id="col1" value="A">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>A</w2:label><w2:value>A</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>B</w2:label><w2:value>B</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>C</w2:label><w2:value>C</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    // col2: inputType=autoComplete + class 설정 (적용 대상)
    strTarget += '<w2:column width="150" inputType="autoComplete" class="apc_color_green" id="col2" value="Apple">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>Apple</w2:label><w2:value>Apple</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>Banana</w2:label><w2:value>Banana</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>Cherry</w2:label><w2:value>Cherry</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    // col3: inputType=select 이지만 class 미설정 (적용할 class 자체가 없음)
    strTarget += '<w2:column width="150" inputType="select" id="col3" value="X">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:item><w2:label>X</w2:label><w2:value>X</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>Y</w2:label><w2:value>Y</w2:value></w2:item>';
    strTarget += '<w2:item><w2:label>Z</w2:label><w2:value>Z</w2:value></w2:item>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:column>';
    // col4: inputType=text + class 설정 (inputType 조건 불성립)
    strTarget += '<w2:column width="150" inputType="text" class="apc_color_red" id="col4" value="hello"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// 공통: cell 클릭하여 편집 모드 진입 → 팝업 (item list) 의 최상위 div class 확인
scwin.openCellAndShowPopupClass = function (rowIndex, colIndex, expectClass, label) {
    let cellEl = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!cellEl) {
        wf_body_bottom.getObj("scwin").setReturnValue(label + " : Cell(" + rowIndex + "," + colIndex + ") DOM 없음");
        return;
    }

    // 1회 클릭 (editModeEvent=onclick 설정으로 인해 편집 모드 진입 → 팝업 표시)
    cellEl.click();

    // gridView cell editor popup 최상위 div 는 'G_{target.id}___{editor}_{row}_{col}_{col}' 형식
    // (예: G_mf_target1___autoComplete_0_col2_col2, G_mf_target1___select_0_col1_col1)
    let popupSelector = "div[id^='G_" + target1.id + "___']";
    let popupList = document.querySelector(popupSelector + ":not([style*='display: none'])");
    let allPopups = document.querySelectorAll(popupSelector);

    wf_body_bottom.getObj("scwin").setReturnValue(label + " : applyColumnClass=" + target1.options.applyColumnClass + ", expectClass='" + expectClass + "'");

    if (allPopups.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue(label + " : cell editor popup 없음");
    } else {
        // 가장 마지막에 생성된 popup 우선 (가장 최근 편집 셀의 popup)
        let target = popupList || allPopups[allPopups.length - 1];
        wf_body_bottom.getObj("scwin").setReturnValue(label + " : popup id=" + target.id + ", popup className='" + target.className + "'");
        wf_body_bottom.getObj("scwin").setReturnValue(label + " : popup 에 '" + expectClass + "' 포함 여부 = " + (expectClass !== "" && target.className.indexOf(expectClass) >= 0));
    }
}



// 1) Cell(0,0): inputType=select + Column class='apc_color_blue'
scwin.btn_checkCol0_onclick = function () {
    scwin.openCellAndShowPopupClass(0, 0, "apc_color_blue", "[Col0 select+class]");
}

// 2) Cell(0,1): inputType=autoComplete + Column class='apc_color_green'
scwin.btn_checkCol1_onclick = function () {
    scwin.openCellAndShowPopupClass(0, 1, "apc_color_green", "[Col1 autoComplete+class]");
}

// 3) Cell(0,2): inputType=select + Column class 미설정 (적용할 class 없음)
scwin.btn_checkCol2_onclick = function () {
    scwin.openCellAndShowPopupClass(0, 2, "", "[Col2 select(class 미설정)]");
}

// 4) Cell(0,3): inputType=text + Column class='apc_color_red' (inputType 조건 불성립)
scwin.btn_checkCol3_onclick = function () {
    // text 셀은 클릭해도 popup 자체가 없어야 함
    scwin.openCellAndShowPopupClass(0, 3, "apc_color_red", "[Col3 text+class]");
}
